import{_ as l,a0 as o,w as d,s as r,I as a,x as e,a1 as i,A as t,ao as p}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const y=JSON.parse('{"title":"如何組織構建多文件 C 語言程序（一） | LCTT x X-CMD","titleTemplate":false,"description":"如何組織構建多文件 C 語言程序（一） | LCTT (202002) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何組織構建多文件 C 語言程序（一） | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何組織構建多文件 C 語言程序（一） | LCTT (202002) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202002/20190729 How to structure a multi-file C program- Part 1","title":"如何組織構建多文件 C 語言程序（一）","tag":"202002","desc":""},"relativePath":"202002/20190729 How to structure a multi-file C program- Part 1.md","filePath":"[post].md"}'),c={name:"202002/20190729 How to structure a multi-file C program- Part 1.md"};function u(g,s,m,h,k,b){const n=o("Link");return d(),r("div",null,[s[35]||(s[35]=a("h1",{id:"如何組織構建多文件-c-語言程序-一",tabindex:"-1"},[e("如何組織構建多文件 C 語言程序（一） "),a("a",{class:"header-anchor",href:"#如何組織構建多文件-c-語言程序-一","aria-label":"Permalink to “如何組織構建多文件 C 語言程序（一）”"},"​")],-1)),s[36]||(s[36]=a("blockquote",null,[a("p",null,"準備好你喜歡的飲料、編輯器和編譯器，放一些音樂，然後開始構建一個由多個文件組成的 C 語言程序。")],-1)),s[37]||(s[37]=a("p",null,[a("img",{src:"https://img.linux.net.cn/data/attachment/album/202002/26/214517o5p7q45l2a8jkx4k.jpg",alt:""})],-1)),s[38]||(s[38]=a("p",null,"大家常説計算機編程的藝術部分是處理複雜性，部分是命名某些事物。此外，我認為“有時需要添加繪圖”是在很大程度上是正確的。",-1)),a("p",null,[s[1]||(s[1]=e("在這篇文章裏，我會編寫一個小型 C 程序，命名一些東西，同時處理一些複雜性。該程序的結構大致基於我在 《",-1)),i(n,{href:"https://linux.cn/article-10949-1.html"},{default:t(()=>[...s[0]||(s[0]=[e("如何寫一個好的 C 語言 main 函數",-1)])]),_:1}),s[2]||(s[2]=e("》 文中討論的。但是，這次做一些不同的事。準備好你喜歡的飲料、編輯器和編譯器，放一些音樂，讓我們一起編寫一個有趣的 C 語言程序。",-1))]),s[39]||(s[39]=a("h3",{id:"優秀-unix-程序哲學",tabindex:"-1"},[e("優秀 Unix 程序哲學 "),a("a",{class:"header-anchor",href:"#優秀-unix-程序哲學","aria-label":"Permalink to “優秀 Unix 程序哲學”"},"​")],-1)),a("p",null,[s[5]||(s[5]=e("首先，你要知道這個 C 程序是一個 ",-1)),i(n,{href:"https://en.wikipedia.org/wiki/Unix"},{default:t(()=>[...s[3]||(s[3]=[e("Unix",-1)])]),_:1}),s[6]||(s[6]=e(" 命令列工具。這意味着它運行在（或者可被移植到）那些提供 Unix C 運行環境的操作系統中。當貝爾實驗室發明 Unix 後，它從一開始便充滿了",-1)),i(n,{href:"http://harmful.cat-v.org/cat-v/"},{default:t(()=>[...s[4]||(s[4]=[e("設計哲學",-1)])]),_:1}),s[7]||(s[7]=e("。用我自己的話來説就是：程序只做一件事，並做好它，並且對文件進行一些操作。雖然“只做一件事，並做好它”是有意義的，但是“對文件進行一些操作”的部分似乎有點兒不合適。",-1))]),s[40]||(s[40]=p('<p>事實證明，Unix 中抽象的 “文件” 非常強大。一個 Unix 文件是以文件結束符（EOF）標誌為結尾的字節流。僅此而已。文件中任何其它結構均由應用程序所施加而非操作系統。操作系統提供了系統調用，使得程序能夠對文件執行一套標準的操作：打開、讀取、寫入、尋址和關閉（還有其他，但説起來那就複雜了）。對於文件的標準化訪問使得不同的程序共用相同的抽象，而且可以一同工作，即使它們是不同的人用不同語言編寫的程序。</p><p>具有共享的文件接口使得構建<em>可組合的</em>的程序成為可能。一個程序的輸出可以作為另一個程序的輸入。Unix 家族的操作系統默認在執行程序時提供了三個文件：標準輸入（<code>stdin</code>）、標準輸出（<code>stdout</code>）和標準錯誤（<code>stderr</code>）。其中兩個文件是隻寫的：<code>stdout</code> 和 <code>stderr</code>。而 <code>stdin</code> 是隻讀的。當我們在常見的 Shell 比如 Bash 中使用文件重定向時，可以看到其效果。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ ls | grep foo | sed -e &#39;s/bar/baz/g&#39; &gt; ack</span></span></code></pre></div><p>這條指令可以被簡要地描述為：<code>ls</code> 的結果被寫入標準輸出，它重定向到 <code>grep</code> 的標準輸入，<code>grep</code> 的標準輸出重定向到 <code>sed</code> 的標準輸入，<code>sed</code> 的標準輸出重定向到當前目錄下文件名為 <code>ack</code> 的文件中。</p><p>我們希望我們的程序在這個靈活又出色的生態系統中運作良好，因此讓我們編寫一個可以讀寫文件的程序。</p><h3 id="喵嗚喵嗚-流編碼器-解碼器概念" tabindex="-1">喵嗚喵嗚：流編碼器/解碼器概念 <a class="header-anchor" href="#喵嗚喵嗚-流編碼器-解碼器概念" aria-label="Permalink to “喵嗚喵嗚：流編碼器/解碼器概念”">​</a></h3>',6)),a("p",null,[s[9]||(s[9]=e("當我還是一個露着豁牙的孩子懵懵懂懂地學習計算機科學時，學過很多編碼方案。它們中的有些用於壓縮文件，有些用於打包文件，另一些毫無用處因此顯得十分愚蠢。列舉最後這種情況的一個例子：",-1)),i(n,{href:"http://www.jabberwocky.com/software/moomooencode.html"},{default:t(()=>[...s[8]||(s[8]=[e("哞哞編碼方案",-1)])]),_:1}),s[10]||(s[10]=e("。",-1))]),a("p",null,[s[12]||(s[12]=e("為了讓我們的程序有個用途，我為它更新了一個 ",-1)),i(n,{href:"https://giphy.com/gifs/nyan-cat-sIIhZliB2McAo"},{default:t(()=>[...s[11]||(s[11]=[e("21 世紀",-1)])]),_:1}),s[13]||(s[13]=e(" 的概念，並且實現了一個名為“喵嗚喵嗚” 的編碼方案的概念（畢竟網上大家都喜歡貓）。這裏的基本的思路是獲取文件並且使用文本 “meow” 對每個半字節（半個字節）進行編碼。小寫字母代表 0，大寫字母代表 1。因為它會將 4 個比特替換為 32 個比特，因此會擴大文件的大小。沒錯，這毫無意義。但是想像一下人們看到經過這樣編碼後的驚訝表情。",-1))]),s[41]||(s[41]=p(`<div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ cat /home/your_sibling/.super_secret_journal_of_my_innermost_thoughts</span></span>
<span class="line"><span>MeOWmeOWmeowMEoW...</span></span></code></pre></div><p>這非常棒。</p><h3 id="最終的實現" tabindex="-1">最終的實現 <a class="header-anchor" href="#最終的實現" aria-label="Permalink to “最終的實現”">​</a></h3>`,3)),a("p",null,[s[15]||(s[15]=e("完整的源代碼可以在 ",-1)),i(n,{href:"https://github.com/JnyJny/meowmeow"},{default:t(()=>[...s[14]||(s[14]=[e("GitHub",-1)])]),_:1}),s[16]||(s[16]=e(" 上面找到，但是我會寫下我在編寫程序時的思考。目的是説明如何組織構建多文件 C 語言程序。",-1))]),s[42]||(s[42]=p(`<p>既然已經確定了要編寫一個編碼和解碼“喵嗚喵嗚”格式的文件的程序時，我在 Shell 中執行了以下的命令 ：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ mkdir meowmeow</span></span>
<span class="line"><span>$ cd meowmeow</span></span>
<span class="line"><span>$ git init</span></span>
<span class="line"><span>$ touch Makefile     # 編譯程序的方法</span></span>
<span class="line"><span>$ touch main.c       # 處理命令列選項</span></span>
<span class="line"><span>$ touch main.h       # “全局”常量和定義</span></span>
<span class="line"><span>$ touch mmencode.c   # 實現對喵嗚喵嗚文件的編碼</span></span>
<span class="line"><span>$ touch mmencode.h   # 描述編碼 API</span></span>
<span class="line"><span>$ touch mmdecode.c   # 實現對喵嗚喵嗚文件的解碼</span></span>
<span class="line"><span>$ touch mmdecode.h   # 描述解碼 API</span></span>
<span class="line"><span>$ touch table.h      # 定義編碼查找表</span></span>
<span class="line"><span>$ touch .gitignore   # 這個文件中的文件名會被 git 忽略</span></span>
<span class="line"><span>$ git add .</span></span>
<span class="line"><span>$ git commit -m &quot;initial commit of empty files&quot;</span></span></code></pre></div><p>簡單的説，我創建了一個目錄，裏面全是空文件，並且提交到 git。</p><p>即使這些文件中沒有內容，你依舊可以從它的文件名推斷每個文件的用途。為了避免萬一你無法理解，我在每條 <code>touch</code> 命令後面進行了簡單描述。</p><p>通常，程序從一個簡單 <code>main.c</code> 文件開始，只有兩三個解決問題的函數。然後程序員輕率地向自己的朋友或者老闆展示了該程序，然後為了支持所有新的“功能”和“需求”，文件中的函數數量就迅速爆開了。“程序俱樂部”的第一條規則便是不要談論“程序俱樂部”，第二條規則是儘量減少單個文件中的函數。</p><p>老實説，C 編譯器並不關心程序中的所有函數是否都在一個文件中。但是我們並不是為計算機或編譯器寫程序，我們是為其他人（有時也包括我們）去寫程序的。我知道這可能有些奇怪，但這就是事實。程序體現了計算機解決問題所採用的一組算法，當問題的參數發生了意料之外的變化時，保證人們可以理解它們是非常重要的。當在人們修改程序時，發現一個文件中有 2049 函數時他們會詛咒你的。</p><p>因此，優秀的程序員會將函數分隔開，將相似的函數分組到不同的文件中。這裏我用了三個文件 <code>main.c</code>、<code>mmencode.c</code> 和 <code>mmdecode.c</code>。對於這樣小的程序，也許看起來有些過頭了。但是小的程序很難保證一直小下去，因此哥忒拓展做好計劃是一個“好主意”。</p><p>但是那些 <code>.h</code> 文件呢？我會在後面解釋一般的術語，簡單地説，它們被稱為頭文件，同時它們可以包含 C 語言類型定義和 C 預處理指令。頭文件中不應該包含任何函數。你可以認為頭文件是提供了應用程序接口（API）的定義的一種 <code>.c</code> 文件，可以供其它 <code>.c</code> 文件使用。</p><h3 id="但是-makefile-是什麼呢" tabindex="-1">但是 Makefile 是什麼呢？ <a class="header-anchor" href="#但是-makefile-是什麼呢" aria-label="Permalink to “但是 Makefile 是什麼呢？”">​</a></h3><p>我知道下一個轟動一時的應用都是你們這些好孩子們用 “終極代碼粉碎者 3000” 集成開發環境來編寫的，而構建項目是用 Ctrl-Meta-Shift-Alt-Super-B 等一系列複雜的按鍵混搭出來的。但是如今（也就是今天），使用 <code>Makefile</code> 文件可以在構建 C 程序時幫助做很多有用的工作。<code>Makefile</code> 是一個包含如何處理文件的方式的文本文件，程序員可以使用其自動地從源代碼構建二進制程序（以及其它東西！）</p><p>以下面這個小東西為例：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>00 # Makefile</span></span>
<span class="line"><span>01 TARGET= my_sweet_program</span></span>
<span class="line"><span>02 $(TARGET): main.c</span></span>
<span class="line"><span>03    cc -o my_sweet_program main.c</span></span></code></pre></div><p><code>#</code> 符號後面的文本是註釋，例如 00 行。</p><p>01 行是一個變量賦值，將 <code>TARGET</code> 變量賦值為字符串 <code>my_sweet_program</code>。按照慣例，也是我的習慣，所有 <code>Makefile</code> 變量均使用大寫字母並用下劃線分隔單詞。</p><p>02 行包含該<ruby>步驟<rt>recipe</rt></ruby>要創建的文件名和其依賴的文件。在本例中，構建<ruby>目標<rt>target</rt></ruby>是 <code>my_sweet_program</code>，其依賴是 <code>main.c</code>。</p><p>最後的 03 行使用了一個製表符號（<code>tab</code>）而不是四個空格。這是將要執行創建目標的命令。在本例中，我們使用 <ruby>C 編譯器<rt>C compiler</rt></ruby>前端 <code>cc</code> 以編譯鏈接為 <code>my_sweet_program</code>。</p><p>使用 <code>Makefile</code> 是非常簡單的。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ make</span></span>
<span class="line"><span>cc -o my_sweet_program main.c</span></span>
<span class="line"><span>$ ls</span></span>
<span class="line"><span>Makefile  main.c  my_sweet_program</span></span></code></pre></div>`,18)),a("p",null,[s[18]||(s[18]=e("構建我們喵嗚喵嗚編碼器/解碼器的 ",-1)),i(n,{href:"https://github.com/JnyJny/meowmeow/blob/master/Makefile"},{default:t(()=>[...s[17]||(s[17]=[e("Makefile",-1)])]),_:1}),s[19]||(s[19]=e(" 比上面的例子要複雜，但其基本結構是相同的。我將在另一篇文章中將其分解為 Barney 風格。",-1))]),s[43]||(s[43]=p(`<h3 id="形式伴隨着功能" tabindex="-1">形式伴隨着功能 <a class="header-anchor" href="#形式伴隨着功能" aria-label="Permalink to “形式伴隨着功能”">​</a></h3><p>我的想法是程序從一個文件中讀取、轉換它，並將轉換後的結果存儲到另一個文件中。以下是我想像使用程序命令列交互時的情況：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ meow &lt; clear.txt &gt; clear.meow</span></span>
<span class="line"><span>$ unmeow &lt; clear.meow &gt; meow.tx</span></span>
<span class="line"><span>$ diff clear.txt meow.tx</span></span>
<span class="line"><span>$</span></span></code></pre></div><p>我們需要編寫代碼以進行命令列解析和處理輸入/輸出流。我們需要一個函數對流進行編碼並將結果寫到另一個流中。最後，我們需要一個函數對流進行解碼並將結果寫到另一個流中。等一下，我們在討論如何寫一個程序，但是在上面的例子中，我調用了兩個指令：<code>meow</code> 和 <code>unmeow</code>？我知道你可能會認為這會導致越變越複雜。</p><h3 id="次要內容-argv-0-和-ln-指令" tabindex="-1">次要內容：argv[0] 和 ln 指令 <a class="header-anchor" href="#次要內容-argv-0-和-ln-指令" aria-label="Permalink to “次要內容：argv[0] 和 ln 指令”">​</a></h3><p>回想一下，C 語言 main 函數的結構如下：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>int main(int argc, char *argv[])</span></span></code></pre></div><p>其中 <code>argc</code> 是命令列參數的數量，<code>argv</code> 是字符指針（字符串）的列表。<code>argv[0]</code> 是包含正在執行的程序的文件路徑。在 Unix 系統中許多互補功能的程序（比如：壓縮和解壓縮）看起來像兩個命令，但事實上，它們是在文件系統中擁有兩個名稱的一個程序。這個技巧是通過使用 <code>ln</code> 命令創建文件系統鏈接來實現兩個名稱的。</p><p>在我筆記本電腦中 <code>/usr/bin</code> 的一個例子如下：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ ls -li /usr/bin/git*</span></span>
<span class="line"><span>3376 -rwxr-xr-x. 113 root root     1.5M Aug 30  2018 /usr/bin/git</span></span>
<span class="line"><span>3376 -rwxr-xr-x. 113 root root     1.5M Aug 30  2018 /usr/bin/git-receive-pack</span></span>
<span class="line"><span>...</span></span></code></pre></div><p>這裏 <code>git</code> 和 <code>git-receive-pack</code> 是同一個文件但是擁有不同的名字。我們説它們是相同的文件因為它們具有相同的 inode 值（第一列）。inode 是 Unix 文件系統的一個特點，對它的介紹超越了本文的內容範疇。</p><p>優秀或懶惰的程序可以通過 Unix 文件系統的這個特點達到寫更少的代碼但是交付雙倍的程序。首先，我們編寫一個基於其 <code>argv[0]</code> 的值而作出相應改變的程序，然後我們確保為導致該行為的名稱創建鏈接。</p><p>在我們的 <code>Makefile</code> 中，<code>unmeow</code> 鏈接通過以下的方式來創建：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># Makefile</span></span>
<span class="line"><span>...</span></span>
<span class="line"><span>$(DECODER): $(ENCODER)</span></span>
<span class="line"><span>        $(LN) -f $&lt; $@</span></span>
<span class="line"><span>       ...</span></span></code></pre></div><p>我傾向於在 <code>Makefile</code> 中將所有內容參數化，很少使用 “裸” 字符串。我將所有的定義都放置在 <code>Makefile</code> 文件頂部，以便可以簡單地找到並改變它們。當你嘗試將程序移植到新的平台上時，需要將 <code>cc</code> 改變為某個 <code>cc</code> 時，這會很方便。</p><p>除了兩個內置變量 <code>$@</code> 和 <code>$&lt;</code> 之外，該<ruby>步驟<rt>recipe</rt></ruby>看起來相對簡單。第一個便是該步驟的目標的快捷方式，在本例中是 <code>$(DECODER)</code>（我能記得這個是因為 <code>@</code> 符號看起來像是一個目標）。第二個，<code>$&lt;</code> 是規則依賴項，在本例中，它解析為 <code>$(ENCODER)</code>。</p><p>事情肯定會變得複雜，但它還在管理之中。</p><hr>`,18)),a("p",null,[s[21]||(s[21]=e("via: ",-1)),i(n,{href:"https://opensource.com/article/19/7/structure-multi-file-c-part-1"},{default:t(()=>[...s[20]||(s[20]=[e("https://opensource.com/article/19/7/structure-multi-file-c-part-1",-1)])]),_:1})]),a("p",null,[s[26]||(s[26]=e("作者：",-1)),i(n,{href:"https://opensource.com/users/jnyjnyhttps://opensource.com/users/jnyjnyhttps://opensource.com/users/jim-salterhttps://opensource.com/users/cldxsolutions"},{default:t(()=>[...s[22]||(s[22]=[e("Erik O'Shaughnessy",-1)])]),_:1}),s[27]||(s[27]=e(" 選題：",-1)),i(n,{href:"https://github.com/lujun9972"},{default:t(()=>[...s[23]||(s[23]=[e("lujun9972",-1)])]),_:1}),s[28]||(s[28]=e(" 譯者：",-1)),i(n,{href:"https://github.com/mengxinayan"},{default:t(()=>[...s[24]||(s[24]=[e("萌新阿巖",-1)])]),_:1}),s[29]||(s[29]=e(" 校對：",-1)),i(n,{href:"https://github.com/wxy"},{default:t(()=>[...s[25]||(s[25]=[e("wxy",-1)])]),_:1})]),a("p",null,[s[32]||(s[32]=e("本文由 ",-1)),i(n,{href:"https://github.com/LCTT/TranslateProject"},{default:t(()=>[...s[30]||(s[30]=[e("LCTT",-1)])]),_:1}),s[33]||(s[33]=e(" 原創編譯，",-1)),i(n,{href:"https://linux.cn/"},{default:t(()=>[...s[31]||(s[31]=[e("Linux中國",-1)])]),_:1}),s[34]||(s[34]=e(" 榮譽推出",-1))])])}const x=l(c,[["render",u]]);export{y as __pageData,x as default};
